  ('souvenir', 'noun', '/ˌsuː.vəˈnɪə/', 'An item of sentimental value, that is given or kept to remember an event or location.', 'I bought a small souvenir for my mum.', 'wiktionary', 'B1', 'cefr-j'),
  ('destination', 'noun', '/dɛstɪˈneɪʃən/', 'The place set for the end of a journey or to which something is sent; place or point aimed at.', 'arrive at your destination', 'wiktionary', 'B1', 'cefr-j'),
  ('journey', 'noun', '/ˈd͡ʒɜːni/', 'A set amount of travelling, seen as a single unit; a discrete trip, a voyage.', 'The journey to London takes two hours by train.', 'wiktionary', 'A2', 'cefr-j'),
